import "./../style/Validate.css";
import logo from "./../images/foufou.jpg";
import green from "./../images/smiley-green.png";
import red from "./../images/smiley-red.png";
import orange from "./../images/smiley-orange.png";
import { supabase } from "./../lib/supabase"
import {
  Document,
  Page,
  Text,
  View,
  StyleSheet,
  PDFDownloadLink,
  Image
} from "@react-pdf/renderer";

const styles = StyleSheet.create({
  page: {
    padding: 30,
  },

  title: {
    fontSize: 20,
    marginBottom: 20,
  },

  divScore: {
    flexDirection: "row",
    alignItems: "center",
  },

  text: {
    fontSize: 12,
    marginBottom: 10,
  },

  bold: {
    fontWeight: "bold",
  },

  smiley: {
    width: 15,
    height: 15,
    marginLeft: 6,
    marginBottom: 10,
  },
});

const getSmiley = (score) => {
  if (score >= 74) return green;
  if (score >= 39) return orange;
  return red;
};

function MyPDF({ dossier, score}) {
  return (
  <Document>
    <Page size="A4" style={styles.page}>

      <Text style={styles.title}>
        {dossier.nameProject}
      </Text>

      <View style={styles.divScore}>

        <Text style={styles.text}>
          <Text style={styles.bold}>Score de viabilité :</Text> {score}
        </Text>

        <Image
          src={getSmiley(score)}
          style={styles.smiley}
        />

      </View>

      <Text style={styles.text}>
        <Text style={styles.bold}>Référent :</Text> {dossier.nom}
      </Text>

      <Text style={styles.text}>
        <Text style={styles.bold}>Commentaire :</Text> {dossier.probabilite}
      </Text>

      <Text style={styles.text}>
        <Text style={styles.bold}>Priorité/s :</Text>
      </Text>

      {dossier.priorite.map((item, index) => (
        <Text style={styles.text} key={item.id ?? index}>
          - {item.question?.title ?? item.value}
        </Text>
      ))}

    </Page>
  </Document>
);
}

function Validate({ message, score, questions = [], bonus = {} , onSave}) {
    

    const today = new Date();

    async function handleSave() {

    const { data: dossier, error: dossierError } = await supabase
  .from("dossier")
  .insert([
    {
      score: score,
      numProject: bonus.numProject,
      nameProject: bonus.nameProject,
      comment: bonus.probabilite,
      avis: bonus.avis,
      owner: bonus.nom
    }
  ])
  .select()
  .single();

if (dossierError) {
  console.error(dossierError);
  return;
}


const criterias = []

questions.map((item) => (
    criterias.push({
        title: item.question?.title,
        score: item.answer,
        priority: item.answer < 3,
        dossier_id: dossier.id
    })
));

bonus.priorite.map((item, index) => {
    if( item.question?.title === undefined){
       criterias.push({
            title: item.value,
            score: null,
            priority: true,
            dossier_id: dossier.id
        })
    }
    });

// Création des critères liés au dossier
const { data: criteria, error: criteriaError } = await supabase
  .from("criteria")
  .insert(criterias);

if (criteriaError) {
  console.error(criteriaError);
  return;
}

onSave()

}

  return (
    <div className="container-validate">

      <div className="card">

        <img className="logo" src={logo} alt="logo" />

        <h2>Récapitulatif du projet</h2>

        <div className={`result-box ${
              score >= 74
                ? "score-green"
                : score >= 39
                ? "score-yellow"
                : "score-red"
            }`}>
          <h3>Résultat</h3>
          <p>{message}</p>
          <strong>Score : {score}/100</strong>
        </div>


        <section>
          <h3>Résultat du formulaire</h3>

          <table className="result-table">
            <thead>
              <tr>
                <th>Critère</th>
                <th>Notation</th>
              </tr>
            </thead>

            <tbody>
              {questions.map((item) => (
                <tr key={item.question.id}>
                  <td>{item.question.title}</td>
                  <td>{item.answer}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>


        <section className="info-section">

          <h3>Informations complémentaires</h3>

          <div className="info-card">

            <p>
              <strong>Numéro de projet</strong> {bonus.numProject}
            </p>

             <p>
              <strong>Nom du projet</strong> {bonus.nameProject}
            </p>

            <p>
              <strong>Date de reception</strong> {today.toLocaleDateString()}
            </p>

            <p>
              <strong>Porteur du projet :</strong> {bonus.nom}
            </p>

            <p>
              <strong>Commentaire :</strong> {bonus.probabilite}
            </p>

            <p>
              <strong>Avis de l'accompagnateur :</strong> {score < 40 ? "A revoir" : score > 70 ? "Ok" : bonus.avis}
            </p>
          </div>

        </section>


        {bonus.priorite?.length > 0 && (
          <section>

            <h3>Priorités du projet</h3>

            <table className="result-table">
              <thead>
                <tr>
                  <th>Priorité</th>
                </tr>
              </thead>

              <tbody>
                {bonus.priorite.map((item, index) => (
                  <tr key={item.id ?? index}>
                    <td>
                      {item.question?.title ?? item.value}
                    </td>
                  </tr>
                ))}
              </tbody>

            </table>

          </section>
        )}

        <button onClick={() => handleSave()}>
        Enregistrer
        </button>
        <button onClick={() => window.print()}>
        Télécharger en PDF
        </button>

       <PDFDownloadLink
  document={<MyPDF dossier={bonus} score={score} />}
  fileName={`${bonus.numProject}_${today.toLocaleDateString()}.pdf`}
  className="pdf-button"
>
  {({ loading }) =>
    loading ? "Création du PDF..." : "Télécharger en PDF client"
  }
</PDFDownloadLink>

      </div>
    </div>
  );
}

export default Validate;